package kim.biryeong.destiny.weapon;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** W322 batch C trait data: exact official socket rolls and DDC PvE base values.
 * Generated by scripts/build_batch_c_w322.py (--verify is read-only). Named local policies live in
 * the resource's localPolicies block; DDC "?"/blank values are never presented as confirmed numbers.
 */
public final class PerkBatchCProfile {
    public static final String GENESIS = "genesis", DISRUPTION_BREAK = "disruption_break",
            SHIELD_DISORIENT = "shield_disorient", ENERGY_TRANSFER = "energy_transfer", INCANDESCENT = "incandescent",
            ADAPTIVE_MUNITIONS = "adaptive_munitions", RIMESTEALER = "rimestealer",
            CRYSTALLINE_CORPSEBLOOM = "crystalline_corpsebloom", SHOOT_TO_LOOT = "shoot_to_loot",
            REDIRECTION = "redirection", ONE_TWO_PUNCH = "one_two_punch";
    public static final long PULSE_MONITOR_ALIAS_HASH = 205890336L;
    private static final List<String> IDS = List.of(GENESIS, DISRUPTION_BREAK, SHIELD_DISORIENT, ENERGY_TRANSFER,
            INCANDESCENT, ADAPTIVE_MUNITIONS, RIMESTEALER, CRYSTALLINE_CORPSEBLOOM, SHOOT_TO_LOOT, REDIRECTION, ONE_TWO_PUNCH);
    private static final Map<String, Long> HASHES = Map.ofEntries(
            Map.entry(GENESIS, 3096702027L), Map.entry(DISRUPTION_BREAK, 1683379515L), Map.entry(SHIELD_DISORIENT, 3275789089L),
            Map.entry(ENERGY_TRANSFER, 2030760728L), Map.entry(INCANDESCENT, 4293542123L), Map.entry(ADAPTIVE_MUNITIONS, 1048183818L),
            Map.entry(RIMESTEALER, 1955165503L), Map.entry(CRYSTALLINE_CORPSEBLOOM, 2922950962L), Map.entry(SHOOT_TO_LOOT, 3700496672L),
            Map.entry(REDIRECTION, 3201496230L), Map.entry(ONE_TWO_PUNCH, 2679249093L));

    public record AdaptiveRule(Map<String, double[]> families, double[] fallback) {
        public double perHit(String family) { return families.getOrDefault(family, fallback)[0]; }
        public double cap(String family) { return families.getOrDefault(family, fallback)[1]; }
    }
    public record DisruptionRule(double kineticMultiplier, int ticks) {}
    public record DisorientRule(double radius, int ticks) {}
    public record GenesisRule(int ammoPerMatchingHit) {}
    public record EnergyTransferRule(double blockedMeleePercent, double blockedPercent, double unblockedPercent,
                                     double guardianHp, double blockedFraction) {}
    public record IncandescentRule(double damagePoints, double radius, int scorchStacks, double powerfulRadius,
                                   int powerfulScorchStacks, int ticksPerScorchStack) {}
    public record RedirectionRule(int gain, int maxStacks, int consume, double bonusPerStack, double maxBonus) {}
    public record OneTwoPunchRule(int pellets, double shotgunMultiplier, double shotgunPvpMultiplier,
                                  double handCannonMultiplier, double handCannonPvpMultiplier, int windowTicks) {}
    public record RimestealerRule(int frostArmorStacks) {}
    public record CorpsebloomRule(int windowTicks, double seekerDistance, int seekerTicks) {}
    public record ShootToLootRule(double brickHitRadius) {}
    public record FrostArmorRule(int maxStacks, int ticks, double resistancePerStack) {}
    public record CrystalRule(int lifetimeTicks, double bodyRadius, double formationRadius, int freezeTicks,
                              double shatterRadius, double shatterDamage, int maxPerLevel) {}
    private record Mechanics(AdaptiveRule adaptiveMunitions, DisruptionRule disruptionBreak, DisorientRule shieldDisorient,
                             GenesisRule genesis, EnergyTransferRule energyTransfer, IncandescentRule incandescent,
                             RedirectionRule redirection, OneTwoPunchRule oneTwoPunch, RimestealerRule rimestealer,
                             CorpsebloomRule crystallineCorpsebloom, ShootToLootRule shootToLoot, FrostArmorRule frostArmor,
                             CrystalRule stasisCrystal) {}
    private record Perk(String id, String name, long hash, int ddcRow, String ddcText, String description, WeaponPerks.Roll[] rolls) {}
    private record Data(String stage, String manifestVersion, Perk[] perks, WeaponPerks.Roll[] pulseMonitorAliases,
                        Mechanics mechanics, Map<String, String> localPolicies) {}
    private record Label(String name, String description, boolean damage, long hash) {}
    private record Labels(Map<String, Label> perks) {}

    private static final Gson GSON = new Gson();
    private static final Data DATA = load();
    private static final Map<String, List<WeaponPerks.Roll>> ROLLS = rollMap();
    private static final Map<String, Label> LABELS = read("/destiny/weapons/w322-batch-c-ko.json", Labels.class).perks;
    private static final Set<String> WEAPONS = weapons();
    private PerkBatchCProfile() {}

    private static <T> T read(String path, Class<T> type) {
        var stream = PerkBatchCProfile.class.getResourceAsStream(path);
        if (stream == null) throw new IllegalStateException("Missing W322 resource " + path);
        try (var reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) { return GSON.fromJson(reader, type); }
        catch (IOException e) { throw new IllegalStateException(e); }
    }
    private static void check(boolean ok, String detail) { if (!ok) throw new IllegalStateException("Invalid W322 batch C: " + detail); }
    private static void roll(WeaponPerks.Roll r, long perkHash) {
        var entry = WeaponCatalog.find(r.id()).orElse(null);
        check(entry != null && WeaponCharacteristics.of(entry).bungieHash() == r.hash() && r.perkHash() == perkHash
                && r.socket() >= 0 && r.socket() < 64 && r.plugSetHash() > 0, "roll " + r);
    }
    private static Data load() {
        var d = read("/destiny/weapons/w322-batch-c.json", Data.class);
        check(d != null && "W322".equals(d.stage) && d.perks != null && d.perks.length == IDS.size() && d.mechanics != null
                && d.pulseMonitorAliases != null && d.pulseMonitorAliases.length > 0, "stage/shape");
        var seen = new HashSet<String>();
        for (var p : d.perks) {
            check(p != null && IDS.contains(p.id) && seen.add(p.id) && HASHES.get(p.id) == p.hash
                    && p.rolls != null && p.rolls.length > 0 && p.ddcText != null && !p.ddcText.isBlank(), "perk " + (p == null ? null : p.id));
            var sockets = new HashSet<String>();
            for (var r : p.rolls) { roll(r, p.hash); check(sockets.add(r.id() + ":" + r.socket()), "duplicate socket " + r); }
        }
        for (var r : d.pulseMonitorAliases) roll(r, PULSE_MONITOR_ALIAS_HASH);
        var m = d.mechanics;
        check(m.adaptiveMunitions != null && m.adaptiveMunitions.fallback != null && m.disruptionBreak != null
                && m.disruptionBreak.kineticMultiplier == 1.5 && m.disruptionBreak.ticks == 110 && m.shieldDisorient != null
                && m.shieldDisorient.radius == 7 && m.shieldDisorient.ticks == 100 && m.genesis != null
                && m.genesis.ammoPerMatchingHit == 1 && m.energyTransfer != null && m.incandescent != null
                && m.incandescent.damagePoints == 30 && m.redirection != null && m.redirection.gain == 2
                && m.redirection.maxStacks == 30 && m.redirection.consume == 3 && m.oneTwoPunch != null
                && m.oneTwoPunch.pellets == 12 && m.oneTwoPunch.windowTicks == 60 && m.rimestealer != null
                && m.crystallineCorpsebloom != null && m.crystallineCorpsebloom.windowTicks == 80
                && m.shootToLoot != null && m.frostArmor != null && m.stasisCrystal != null, "DDC mechanics");
        return d;
    }
    private static Map<String, List<WeaponPerks.Roll>> rollMap() {
        var map = new LinkedHashMap<String, List<WeaponPerks.Roll>>();
        for (var p : DATA.perks) map.put(p.id, List.of(p.rolls));
        return Map.copyOf(map);
    }
    private static Set<String> weapons() {
        var set = new HashSet<String>();
        ROLLS.values().forEach(list -> list.forEach(r -> set.add(r.id())));
        return Set.copyOf(set);
    }
    public static List<String> ids() { return IDS; }
    public static boolean has(String id) { return id != null && ROLLS.containsKey(id); }
    public static List<WeaponPerks.Roll> rolls(String id) { return ROLLS.getOrDefault(id, List.of()); }
    public static long hash(String id) { return HASHES.getOrDefault(id, 0L); }
    /** Fast pre-filter: does this catalog weapon roll any batch C trait. */
    public static boolean rolledBy(String weaponId) { return WEAPONS.contains(weaponId); }
    public static String name(String id) { var l = LABELS.get(id); return l == null ? id : l.name(); }
    public static List<WeaponPerks.Roll> pulseMonitorAliases() { return List.of(DATA.pulseMonitorAliases); }
    public static AdaptiveRule adaptive() { return DATA.mechanics.adaptiveMunitions; }
    public static DisruptionRule disruption() { return DATA.mechanics.disruptionBreak; }
    public static DisorientRule disorient() { return DATA.mechanics.shieldDisorient; }
    public static GenesisRule genesis() { return DATA.mechanics.genesis; }
    public static EnergyTransferRule energyTransfer() { return DATA.mechanics.energyTransfer; }
    public static IncandescentRule incandescent() { return DATA.mechanics.incandescent; }
    public static RedirectionRule redirection() { return DATA.mechanics.redirection; }
    public static OneTwoPunchRule oneTwoPunch() { return DATA.mechanics.oneTwoPunch; }
    public static RimestealerRule rimestealer() { return DATA.mechanics.rimestealer; }
    public static CorpsebloomRule corpsebloom() { return DATA.mechanics.crystallineCorpsebloom; }
    public static ShootToLootRule shootToLoot() { return DATA.mechanics.shootToLoot; }
    public static FrostArmorRule frostArmor() { return DATA.mechanics.frostArmor; }
    public static CrystalRule crystal() { return DATA.mechanics.stasisCrystal; }
}
